16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
23	    @Mapping(target = "initials", expression = "java(initials(owner))")
24	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
25	    @Mapping(target = "membershipTier", expression = "java(membershipTier(owner))")
26	    @Mapping(target = "locality", expression = "java(locality(owner))")
27	    OwnerDto toOwnerDto(Owner owner);
28	
29	    /** The canonical region derived from the owner's city via the fixed city-to-region table,
30	     * or 'UNKNOWN' when the city is not in the table. */
31	    default String locality(Owner owner) {
32	        if (owner == null) {
33	            return null;
34	        }
35	        return Locality.forCity(owner.getCity());
36	    }
37	
38	    /** Format the stored names as 'LastName, FirstName'. */
39	    default String displayName(Owner owner) {
40	        if (owner == null) {
41	            return null;
42	        }
43	        return owner.getLastName() + ", " + owner.getFirstName();
44	    }
45	
46	    /** The upper-cased first letters of firstName and lastName, dot-separated with a trailing dot (e.g. 'J.S.'). */
47	    default String initials(Owner owner) {
48	        if (owner == null) {
49	            return null;
50	        }
51	        return initial(owner.getFirstName()) + initial(owner.getLastName());
52	    }
53	
54	    private static String initial(String name) {
55	        if (name == null || name.isEmpty()) {
56	            return "";
57	        }
58	        return Character.toUpperCase(name.charAt(0)) + ".";
59	    }
60	
61	    /**
62	     * The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the
63	     * last two digits of the registrationDate year (e.g. 'LON-SMI-0007-M26'). Derived from the owner's
64	     * own fields; null until both the customer code and registration date are assigned.
65	     */
66	    default String membershipNumber(Owner owner) {
67	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
68	            return null;
69	        }
70	        return owner.getCustomerCode() + "-M" + String.format("%02d", owner.getRegistrationDate().getYear() % 100);
71	    }
72	
73	    /**
74	     * The owner's membership tier, derived from the owner's own fields: 'GOLD' when the owner's
75	     * household has 3 or more members (householdSize is 3+); otherwise 'SILVER' when the owner has
76	     * no namesakes (namesakeCount is 0) and an email is present, and 'BRONZE' in all other cases.
77	     */
78	    default OwnerDto.MembershipTierEnum membershipTier(Owner owner) {
79	        if (owner == null) {
80	            return null;
81	        }
82	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
83	            return OwnerDto.MembershipTierEnum.GOLD;
84	        }
85	        boolean unique = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
86	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
87	        return unique && hasEmail ? OwnerDto.MembershipTierEnum.SILVER : OwnerDto.MembershipTierEnum.BRONZE;
88	    }
