7	/**
8	 * Records how many owners the new owner's household holds once this owner is added: the
9	 * existing owners already assigned this owner's {@code householdId} by
10	 * {@link AssignOwnerHousehold} plus the new owner itself. An owner that does not share a
11	 * household ({@code householdId} is null) has a household size of 1.
12	 *
13	 * <p>Runs after {@link AssignOwnerHousehold} and before {@link SaveOwner}, so the count
14	 * reflects the household membership at creation time and never counts the new owner twice.
15	 */
16	public class AssignOwnerHouseholdSize {
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
19	        int count = 1; // the new owner, not yet saved
20	        String householdId = owner.getHouseholdId();
21	        if (householdId != null) {
22	            for (Owner existing : ownerRepository.findAll()) {
23	                if (householdId.equals(existing.getHouseholdId())) {
24	                    count++;
25	                }
26	            }
27	        }
28	        owner.setHouseholdSize(count);
29	    }
30	}
